window.MGProseData("d700cf66abacf3ba81134f3b8ac40f48589845bfdd346914dccdbdf2984ba07f",{"html":"\u003cp>\u003cstrong>S1.\u003c/strong> 记商映射为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q:Y\\to Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。取收缩\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nh:A\\times I\\longrightarrow A,\\qquad h(a,0)=a,\\quad h(a,1)=a_0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>⊆\u003c/mo>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\\subseteq Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 CW 子复形，包含映射具有同伦延拓性质。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可延拓为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>F\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>h\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nF:Y\\times I\\longrightarrow Y,\\qquad F(y,0)=y,\\quad F|_{A\\times I}=h.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上恒为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故存在连续映射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>g\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng:Y/A\\longrightarrow Y,\\qquad gq=F_1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003cmi>q\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>Y\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">gq\\simeq\\operatorname{id}_Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>另一方面，对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，都有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_t(A)\\subseteq A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>F\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline F(q(y),t)=q(F(y,t))\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义良好。这也是连续的联合同伦：有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 紧致 Hausdorff，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 闭，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y/A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 Hausdorff；连续满射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmo>×\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>I\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq\\times\\operatorname{id}_I:Y\\times I\\longrightarrow (Y/A)\\times I\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是紧空间到 Hausdorff 空间的闭映射，因而是商映射。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">qF\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 确实连续地下降到商。\u003c/p>\n\u003cp>该同伦满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">id\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>A\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>F\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi>g\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\overline F_0=\\operatorname{id}_{Y/A},\\qquad \\overline F_1=qg.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是同伦等价。下降的关键是构造保证了整个同伦过程中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_t(A)\\subseteq A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>\u003cstrong>S2.\u003c/strong> 先证明一个后面也会使用的映射锥事实。对映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f:L\\to D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>⨿\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∼\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>L\u003c/mi>\u003cmo>×\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> 压为一点\u003c/mtext>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC(f)=\\bigl(D\\amalg(L\\times I)\\bigr)/\n\\bigl((x,0)\\sim f(x),\\ L\\times\\{1\\}\\text{ 压为一点}\\bigr).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H:f\\simeq g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Phi_H:C(f)\\longrightarrow C(g)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为恒等，并在锥上定义为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Φ\u003c/mi>\u003cmi>H\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>t\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Phi_H([x,t])=\n\\begin{cases}\nH(x,2t),\u0026amp;0\\le t\\le \\tfrac12,\\\\\n[x,2t-1],\u0026amp;\\tfrac12\\le t\\le1.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两段在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=\\tfrac12\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 处一致，也尊重底部和锥顶的识别，故给出连续映射。\u003c/p>\n\u003cp>反向同伦 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\overline H(x,s)=H(x,1-s)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 给出反向映射。两种复合都是先沿同伦往返，再进入原锥，仅各段参数长度有所改变。线性调整这些长度后，往返部分可连续缩为常值：例如令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>u\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>u\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mstyle>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\rho(u)=\n\\begin{cases}\n2u,\u0026amp;u\\le\\tfrac12,\\\\\n2-2u,\u0026amp;u\\ge\\tfrac12,\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH(x,(1-s)\\rho(u))\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在端点不动下把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后接其逆的路径缩为常值路径。最后把剩余常值领圈的长度缩为零，即得到恒等映射。另一复合同理。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>g\u003c/mi>\u003cmspace width=\"1em\"/>\u003cmo>⟹\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf\\simeq g\\quad\\Longrightarrow\\quad C(f)\\simeq C(g),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而且这些同伦在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上保持不动。\u003c/p>\n\u003cp>现在令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>↪\u003c/mo>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i:L\\hookrightarrow D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。题设给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\\simeq c_{d_0}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通，可将零伦接上一条路径，使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是任意指定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 胞腔。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nY=C(i)\\simeq C(c_{d_0}).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对常值映射，整个锥底被粘到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>L\u003c/mi>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∨\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC(c_{d_0})\n\\cong D\\vee\\bigl(CL/L\\bigr)\n= D\\vee\\Sigma L.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>楔点在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在非约化悬挂中取“锥底压缩所得”的悬点。两个悬点可由悬挂反射交换；不同的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>d\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">d_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的路径连接，相应常值映射同伦，故所得同伦类型不变。这里没有要求 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连通。\u003c/p>\n\u003cp>\u003cstrong>S3.\u003c/strong> 先记录一个删去顶点的事实。对有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nD=\\{\\sigma\\in K:v\\notin\\sigma\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在通常的重心坐标中，对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\ne v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>v\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmi>v\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmtext> \u003c/mtext>\u003cmi>u\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nr(x)=\\sum_{u\\ne v}\\frac{t_u(x)}{1-t_v(x)}\\,u.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它落在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中。直线同伦\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nR_s(x)=(1-s)x+s\\,r(x)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n始终位于承载 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形内，且不会经过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并逐点固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo>↘\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\setminus\\{v\\}\\ \\searrow\\ |D|\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是强形变收缩。\u003c/p>\n\u003cp>现取题给的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，添加两个新顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v,w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=L*\\{v,w\\}=(v*L)\\cup_L(w*L),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{v,w\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是没有边的两点复形。选择 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为边 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[v,a]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其所有面。\u003c/p>\n\u003cp>此时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\\cong\\Sigma|L|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而删除子复形为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>L\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w*L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，是非空可缩的锥。因此上述形变收缩说明\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\setminus\\{v\\}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n非空且可缩。\u003c/p>\n\u003cp>又有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\\cong[0,1]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对应 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\\setminus\\{v\\}\\cong(0,1]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。包含映射的同伦逆可取到端点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的常值映射；同伦\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nh_s(t)=(1-s)t+s\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在这两个区间上均适用，故该包含确为同伦等价。\u003c/p>\n\u003cp>对非空空间，两个开锥邻域的 Mayer–Vietoris 序列给出悬挂同构\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_n(\\Sigma|L|;R)\n\\cong \\widetilde H_{n-1}(|L|;R),\\qquad n\\ge1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb{RP}^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的标准胞腔链复形中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是乘以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmi mathvariant=\"double-struck\">P\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>对所有 \u003c/mtext>\u003cmi>n\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_1(\\mathbb{RP}^2;\\mathbb Z)=\\mathbb Z/2,\n\\qquad\n\\widetilde H_n(\\mathbb{RP}^2;\\mathbb Q)=0\\quad\\text{对所有 }n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n悬挂又是连通的，因而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmo>∗\u003c/mo>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Q\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\widetilde H_*(|K|;\\mathbb Q)=0,\n\\qquad\n\\widetilde H_2(|K|;\\mathbb Z)=\\mathbb Z/2\\ne0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|K|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可缩，全部要求均满足。\u003c/p>\n\u003cp>\u003cstrong>S4.\u003c/strong> 可能的同伦类型恰好是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>M\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmspace width=\"1em\"/>\u003cmtext>其中 \u003c/mtext>\u003cmi>M\u003c/mi>\u003cmtext> 为任意非空有限单纯复形。 \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\ \\Sigma|M|\\quad\\text{其中 }M\\text{ 为任意非空有限单纯复形。}\\ }\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>先证明必要性。仍记删除子复形为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并记链环为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>τ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>τ\u003c/mi>\u003cmo>∪\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Lambda=\\operatorname{lk}_K(v)\n=\\{\\tau\\in K:v\\notin\\tau,\\ \\tau\\cup\\{v\\}\\in K\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 S3 的形变收缩，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\\simeq O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空且可缩。\u003c/p>\n\u003cp>此外，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必须属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的某条边。否则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|B|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的孤立分支，而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|B|\\setminus\\{v\\}\\longrightarrow |B|\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在路径分支上不满射，不可能是同伦等价。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空。\u003c/p>\n\u003cp>单纯复形的分解给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>D\u003c/mi>\u003cmo>∪\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>D\u003c/mi>\u003cmo>∩\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=D\\cup(v*\\Lambda),\\qquad D\\cap(v*\\Lambda)=\\Lambda.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对有限 CW 对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(|K|,|D|)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 应用 S1，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\simeq X/|D|\n\\cong (C|\\Lambda|)/|\\Lambda|\n=\\Sigma|\\Lambda|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里商空间的识别使用了 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\\ne\\varnothing\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：被压缩的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|D|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 正对应于锥底压缩所得的悬点。\u003c/p>\n\u003cp>反过来，给定任意非空有限复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=M*\\{v,w\\},\\qquad B=[v,a]\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的任一顶点。与 S3 完全相同，删除子复形是可缩锥 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003cmo>∗\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w*M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而边去掉 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后包含到整条边是同伦等价。因此每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>M\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|M|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都满足原条件得到实现。\u003c/p>\n\u003cp>可缩的局部判据为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmi>X\u003c/mi>\u003cmtext> 可缩\u003c/mtext>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lk\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>对所有 \u003c/mtext>\u003cmi>q\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0.\u003c/mn>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\nX\\text{ 可缩}\n\\iff\n\\widetilde H_q(\\operatorname{lk}_K(v);\\mathbb Z)=0\n\\quad\\text{对所有 }q\\ge0.\n\\quad}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>必要性来自 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\simeq\\Sigma|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和悬挂同调同构。\u003c/p>\n\u003cp>证明充分性。若右边成立，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>H\u003c/mi>\u003cmo stretchy=\"true\">~\u003c/mo>\u003c/mover>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\widetilde H_0(\\Lambda;\\mathbb Z)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是非空有限复形，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 路径连通。悬挂的两个开锥邻域均可缩，其交集同伦等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 van Kampen 定理说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 单连通。悬挂同构又说明它的约化整数同调全零。\u003c/p>\n\u003cp>单连通且整数同调平凡的 CW 复形可缩：从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\pi_1=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 开始，逐次应用 Hurewicz 定理得到所有高阶同伦群为零，再对它到一点的映射应用 Whitehead 定理。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma|\\Lambda|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可缩。\u003c/p>\n\u003cp>最后说明如何只用题目要求的有限关联数据检验此判据。链环中的每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>q\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 单形\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{u_0,\\ldots,u_q\\}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n恰对应于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>q\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(q+1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 单形\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{v,u_0,\\ldots,u_q\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n链环中的面关系，也恰对应于这些单形之间保留 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的面关系。任意排列邻接顶点后，即可由这些关联写出增广整数链复形\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmover>\u003cmo stretchy=\"true\" minsize=\"3.0em\">→\u003c/mo>\u003cmpadded width=\"+0.6em\" lspace=\"0.3em\">\u003cmi>ϵ\u003c/mi>\u003c/mpadded>\u003c/mover>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n0\\longrightarrow C_m(\\Lambda;\\mathbb Z)\n\\longrightarrow\\cdots\\longrightarrow\nC_0(\\Lambda;\\mathbb Z)\n\\xrightarrow{\\epsilon}\\mathbb Z\n\\longrightarrow0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmi>q\u003c/mi>\u003c/munderover>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>i\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo stretchy=\"true\">^\u003c/mo>\u003c/mover>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>q\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>ϵ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\partial[u_0,\\ldots,u_q]\n=\\sum_{i=0}^q(-1)^i\n[u_0,\\ldots,\\widehat u_i,\\ldots,u_q],\n\\qquad \\epsilon([u])=1.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所求条件就是这个有限链复形处处正合，可通过整数矩阵计算，例如 Smith 标准形检验。整个计算只使用含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单形及其面关联。必须使用整数系数；S3 表明有理系数会漏掉挠性障碍。\u003c/p>\n\u003cp>\u003cstrong>S5.\u003c/strong> 不一定；新增的可能类型恰好只有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{S^0.}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>事实上，不需要 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，S3 的形变收缩仍说明删除子复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>D\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">D\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空可缩。\u003c/p>\n\u003cp>若链环 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Lambda\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空，S4 的商空间证明仍然适用，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Λ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|\\simeq\\Sigma|\\Lambda|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若链环没有顶点，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是孤立顶点，从而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>D\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>⨿\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>≃\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>⨿\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo>∗\u003c/mo>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|K|=|D|\\amalg\\{v\\}\\simeq\\{\\ast\\}\\amalg\\{\\ast\\}=S^0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>任何非空空间的非约化悬挂都路径连通，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可能同伦等价于题目要求的悬挂。它可由只有两个孤立顶点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>w\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v,w\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的复形实现，此时删去 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后只剩一点。原来的全部悬挂类型仍由 S4 的构造实现，故分类完整。\u003c/p>\n\u003cp>\u003cstrong>S6.\u003c/strong> 不必。取有限单纯复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_1,L_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，分别实现\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n|L_1|\\cong T^2,\\qquad\n|L_2|\\cong S^1\\vee S^1\\vee S^2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n前者可取环面的有限三角剖分；后者可将两个多边形圆和一个三角剖分的球面在一个顶点处粘合，得到有限单纯复形。\u003c/p>\n\u003cp>它们不同伦等价，因为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_1(T^2)=\\mathbb Z^2,\\qquad\n\\pi_1(S^1\\vee S^1\\vee S^2)=F_2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n前者交换，后者不交换。\u003c/p>\n\u003cp>下面证明它们的悬挂同伦等价。对基点为顶点的有限 CW 复形 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，非约化悬挂中的基点经线是一条可缩子复形。由 S1，压缩这条经线得到的约化悬挂 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Sigma_r Z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>Z\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmi>Z\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma Z\\simeq\\Sigma_r Z.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>环面有一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 胞腔、两个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 胞腔和一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 胞腔。以其 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 胞腔为基点，约化悬挂将非基点胞腔的维数增加一，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmo>∪\u003c/mo>\u003cmi>α\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>D\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r T^2=(S^2\\vee S^2)\\cup_\\alpha D^3\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha:S^2\\to S^2\\vee S^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>悬挂同构给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH_3(\\Sigma_r T^2;\\mathbb Z)\n\\cong H_2(T^2;\\mathbb Z)=\\mathbb Z.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此其胞腔边界\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo>⟶\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\partial_3:\\mathbb Z\\longrightarrow\\mathbb Z^2\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n必须为零；它的两个坐标正是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对两个球面的度数。于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 Hurewicz 像为零。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S^2\\vee S^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是单连通 CW 复形，Hurewicz 同构\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">;\u003c/mo>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\pi_2(S^2\\vee S^2)\\cong H_2(S^2\\vee S^2;\\mathbb Z)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n说明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>α\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\alpha\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 零伦。应用 S2 证明中的映射锥引理，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>≃\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r T^2\\simeq S^2\\vee S^2\\vee S^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>另一方面，约化悬挂与有限楔和交换，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≅\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∨\u003c/mo>\u003cmsup>\u003cmi>S\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma_r(S^1\\vee S^1\\vee S^2)\n\\cong S^2\\vee S^2\\vee S^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n结合约化与非约化悬挂的比较，最终得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≃\u003c/mo>\u003cmi mathvariant=\"normal\">Σ\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≄\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\Sigma|L_1|\\simeq\\Sigma|L_2|,\n\\qquad\n|L_1|\\not\\simeq|L_2|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n","source":"assets/content/d700cf66abacf3ba81134f3b8ac40f48589845bfdd346914dccdbdf2984ba07f.html"});
